-- plumblink-superbia (researched)
UPDATE businesses SET description = 'Plumblink Polokwane is a plumbing, bathroom and kitchenware retailer and supplier, part of the national Plumblink network. The branch''s own current page on the Plumblink website confirms this product range and gives the store''s present trading address, which differs from older listings still circulating for the branch.

Customers needing plumbing fixtures and fittings, bathroom ware or kitchen-related products can source them from the branch whether they are a plumber buying for a job or a homeowner working on a renovation. The store trades from Kobalt Street in Polokwane Extension 13, and is open from seven until half past four on weekdays from Monday to Thursday, seven until four on Fridays, and eight until one on Saturdays.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.plumblink.co.za/store/plumblink-polokwane'), description_enriched_at = datetime('now') WHERE slug = 'plumblink-superbia' AND description = 'Plumblink Polokwane is the Superbia branch of Plumblink, South Africa''s largest plumbing, bathroom and kitchenware retailer, part of the Bidvest group, supplying plumbing fixtures and fittings to trade and DIY customers.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
